from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def __init__(self, data):
        self.data = data

    def sort(self):
        n = len(self.data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(self.data[j], self.data[j + 1]):
                    self.swap(j, j + 1)

    @abstractmethod
    def compare(self, a, b):
        pass

    @abstractmethod
    def swap(self, i, j):
        pass

class BubbleSort(SortAlgorithm):
    def compare(self, a, b):
        return a > b

    def swap(self, i, j):
        self.data[i], self.data[j] = self.data[j], self.data[i]

class SelectionSort(SortAlgorithm):
    def compare(self, a, b):
        return a > b

    def swap(self, i, j):
        self.data[i], self.data[j] = self.data[j], self.data[i]

    def sort(self):
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(self.data[min_idx], self.data[j]):
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)

